				{
					instance.reserveSaveEnable = true;
				}
				throw ex3;
			}
			finally
			{
				if (instance != null && instance.reserveSaveEnable && instance.reserveSave != 0)
				{
					int reserveSave = instance.reserveSave;
					instance.reserveSave = 0;
					for (int j = 0; j < 3; j++)
					{
						try
						{
							switch (reserveSave)
							{
							case 1:
								instance.Save();
								break;
							case 2:
								instance.SaveAll();
								break;
							}
						}
						catch (Exception)
						{
							JSystem.Gc();
							JThread.Sleep(500L);
							continue;
						}
						break;
					}
				}
			}
		}

